/// Короткі описи ключових параметрів українською (заголовок, пояснення). Для решти використовується опис з метаданих ArduPilot.
enum ParamTexts {
    /// Нормалізація імені: BATT2_x → BATT_x, Q_M_x → MOT_x.
    static func key(_ name: String) -> String {
        var n = name
        if n.hasPrefix("Q_M_") { n = "MOT_" + n.dropFirst(4) }
        if let r = n.range(of: #"^BATT[2-9]_"#, options: .regularExpression) { n = "BATT_" + n[r.upperBound...] }
        if let r = n.range(of: #"^GPS[2-9]_"#, options: .regularExpression) { n = "GPS1_" + n[r.upperBound...] }
        if let r = n.range(of: #"^ARSPD2_"#, options: .regularExpression) { n = "ARSPD_" + n[r.upperBound...] }
        if let r = n.range(of: #"^EK3_SRC[2-3]_"#, options: .regularExpression) { n = "EK3_SRC1_" + n[r.upperBound...] }
        if let r = n.range(of: #"^(RNGFND|MNT|CAM|PRX)[2-9]_"#, options: .regularExpression) { n = String(n[n.startIndex..<n.index(n.startIndex, offsetBy: n.distance(from: n.startIndex, to: r.upperBound) - 2)]) + "1_" + n[r.upperBound...] }
        if let r = n.range(of: #"^CAN_[PD][2-3]_"#, options: .regularExpression) { n = String(n.prefix(5)) + "1_" + n[r.upperBound...] }
        if n == "FS_GCS_ENABL" { n = "FS_GCS_ENABLE" }
        if n == "GPS_TYPE" { n = "GPS1_TYPE" }
        return n
    }

    static func info(_ name: String) -> (title: String, text: String)? {
        if AppLanguage.isEnglish { return nil }
        guard let i = table[key(name)] else { return nil }
        var title = i.title
        if name.range(of: #"^BATT[2-9]_"#, options: .regularExpression) != nil { title += " (батарея \(name.dropFirst(4).first!))" }
        else if name.range(of: #"^GPS[2-9]_"#, options: .regularExpression) != nil { title += " (GPS \(name.dropFirst(3).first!))" }
        else if name.hasPrefix("ARSPD2_") { title += " (датчик 2)" }
        else if let r = name.range(of: #"^(RNGFND|MNT|CAM|PRX)([2-9])_"#, options: .regularExpression) { title += " (№\(name[name.index(r.upperBound, offsetBy: -2)]))" }
        else if name.range(of: #"^EK3_SRC[2-3]_"#, options: .regularExpression) != nil { title += " (набір \(name.dropFirst(7).first!))" }
        return (title, i.text)
    }

