        // Датчик повітряної швидкості
        "ARSPD_TYPE": ("Тип датчика швидкості", "Модель датчика повітряної швидкості (трубка Піто) і спосіб підключення: аналоговий вхід, I²C або DroneCAN."),
        "ARSPD_USE": ("Використовувати в польоті", "Якщо вимкнено, швидкість лише показується й пишеться в лог, але не впливає на керування."),
        "ARSPD_PRIMARY": ("Основний датчик", "Який із двох датчиків вважати основним."),
        "ARSPD_PIN": ("Пін датчика (аналоговий)", "Аналоговий вхід плати, до якого підключено датчик."),
        "ARSPD_BUS": ("Шина I²C", "Номер шини I²C, до якої підключено датчик."),
        "ARSPD_AUTOCAL": ("Автокалібрування коефіцієнта", "Автопілот сам уточнює коефіцієнт датчика в польоті, порівнюючи швидкість із GPS. Вмикайте на час налаштування, потім вимкніть."),
        "ARSPD_RATIO": ("Коефіцієнт датчика", "Множник перетворення тиску на швидкість. Типове значення залежить від моделі датчика."),
        "ARSPD_OFFSET": ("Нульове зміщення", "Показ датчика при нульовій швидкості. Калібрується кнопкою «Калібрувати нуль» на цій сторінці."),
        "ARSPD_SKIP_CAL": ("Пропускати калібрування нуля", "Не вимагати калібрування нуля при кожному вмиканні. Не рекомендується, бо знижує точність."),
        "ARSPD_PSI_RANGE": ("Діапазон датчика, PSI", "Максимальний тиск, який вимірює датчик. Для MS4525 типово 1 PSI."),
        "ARSPD_TUBE_ORDR": ("Порядок трубок", "Яка трубка (повного чи статичного тиску) підключена до якого входу. Помилка дає від'ємну швидкість."),
        "ARSPD_OFF_PCNT": ("Допуск калібрування нуля, %", "Максимальна дозволена помилка швидкості під час калібрування нуля."),
        "ARSPD_OPTIONS": ("Додаткові опції", "Бітова маска поведінки датчика, наприклад автоматичне вимкнення при розбіжності зі швидкістю GPS."),
        "ARSPD_WIND_MAX": ("Допустима розбіжність з вітром, м/с", "Якщо швидкість за датчиком відрізняється від оцінки за GPS і вітром більше за це значення, датчик вважається несправним. 0 вимикає."),
        "ARSPD_WIND_WARN": ("Поріг попередження про розбіжність, м/с", "Різниця швидкостей, при якій з'являється попередження про можливу несправність датчика. 0 вимикає."),
        "ARSPD_WIND_GATE": ("Чутливість перевірки вітру", "Наскільки суворо порівнюється швидкість датчика з оцінкою за GPS і вітром."),
        // GPS і навігація
        "GPS1_TYPE": ("Тип GPS-приймача", "Протокол приймача. AUTO підходить для більшості модулів u-blox; змінюйте лише якщо автовизначення не працює."),
        "GPS1_GNSS_MODE": ("Супутникові системи", "Які системи використовувати: GPS, GLONASS, Galileo, BeiDou. 0 залишає типові налаштування приймача."),
        "GPS1_RATE_MS": ("Період оновлення, мс", "Як часто приймач видає позицію: 200 мс = 5 Гц, 100 мс = 10 Гц."),
        "GPS1_POS_X": ("Положення антени вперед, м", "Зміщення антени GPS уперед від центру апарата. Покращує точність при поворотах."),
        "GPS1_POS_Y": ("Положення антени вправо, м", "Зміщення антени GPS праворуч від центру апарата."),
        "GPS1_POS_Z": ("Положення антени вниз, м", "Зміщення антени GPS вниз від центру апарата (над центром значення від'ємне)."),
        "GPS1_DELAY_MS": ("Затримка приймача, мс", "Скільки мілісекунд проходить від виміру до отримання даних автопілотом. Зазвичай залишають типове значення."),
        "GPS1_COM_PORT": ("Порт приймача", "Номер послідовного порту, до якого підключено GPS."),
