        "GPS_AUTO_CONFIG": ("Автоналаштування приймача", "Автопілот сам налаштовує приймач u-blox на потрібну частоту й протокол."),
        "GPS_AUTO_SWITCH": ("Вибір між двома GPS", "Як вибирати основний GPS: за кількістю супутників, за якістю або змішуванням двох."),
        "GPS_PRIMARY": ("Основний GPS", "Який приймач вважати основним, якщо їх два."),
        "GPS_BLEND_MASK": ("Критерії змішування двох GPS", "За якими параметрами (горизонтальна точність, швидкість, висота) змішувати дані двох приймачів."),
        "GPS_MIN_ELEV": ("Мін. кут супутників, °", "Супутники нижче цього кута над горизонтом ігноруються. -100 залишає типове значення приймача."),
        "GPS_NAVFILTER": ("Модель руху приймача", "Профіль динаміки для внутрішнього фільтра приймача: літак, мультикоптер, пішохід тощо."),
        "GPS_SBAS_MODE": ("Режим SBAS", "Підвищення точності за допомогою супутникових систем доповнення (WAAS, EGNOS)."),
        "GPS_SAVE_CFG": ("Збереження налаштувань у приймачі", "Чи зберігати налаштування автопілота в пам'яті приймача."),
        "GPS_RAW_DATA": ("Запис сирих даних", "Записувати сирі дані приймача для постобробки (RTK/PPK)."),
        "GPS_DRV_OPTIONS": ("Опції драйвера", "Додаткові опції драйвера GPS."),
        "AHRS_GPS_USE": ("Використовувати GPS у навігації", "Якщо вимкнути, AHRS не користується GPS (наприклад, для польоту без GPS з оптичною одометрією)."),
        "AHRS_GPS_GAIN": ("Вага GPS в AHRS", "Наскільки AHRS довіряє GPS. 1 стандартно, 0 ігнорувати."),
        "AHRS_GPS_MINSATS": ("Мін. супутників для GPS", "Якщо супутників менше, GPS не використовується в AHRS."),
        "AHRS_EKF_TYPE": ("Фільтр навігації", "Який EKF рахує положення. 3 = EKF3 (рекомендовано)."),
        "EK3_ENABLE": ("Увімкнути EKF3", "Основний сучасний фільтр навігації ArduPilot."),
        "EK3_SRC1_POSXY": ("Джерело горизонтальної позиції", "Звідки береться позиція XY: GPS, ExternalNav (оптична одометрія), маяки тощо."),
        "EK3_SRC1_VELXY": ("Джерело горизонтальної швидкості", "Звідки береться швидкість XY: GPS, оптичний потік, ExternalNav тощо."),
        "EK3_SRC1_POSZ": ("Джерело висоти", "Зазвичай барометр. Може бути далекомір, GPS або ExternalNav."),
        "EK3_SRC1_VELZ": ("Джерело вертикальної швидкості", "Звідки береться вертикальна швидкість: GPS, ExternalNav або ніде (None)."),
