    /// Перше речення опису з метаданих (для підпису під параметром).
    static func shortDoc(_ doc: String?) -> String? {
        guard var d = doc?.trimmingCharacters(in: .whitespacesAndNewlines), !d.isEmpty else { return nil }
        if let r = d.range(of: ". ") { d = String(d[..<r.lowerBound]) + "." }
        return d.count > 160 ? String(d.prefix(157)) + "…" : d
    }
}
